-- runtime_config.lua is generated by entrypoint.sh at container start
local config = dofile_once("mods/noita-docker-harness/runtime_config.lua") or {}

if config.seed then
  SetWorldSeed(config.seed)
end

function OnPlayerSpawned()
  -- Z:\ is Wine's mapping of the host root, so this writes to /appdata on the
  -- host (which itself is a docker container with /appdata mapped outside of it).
  io.open([[Z:\appdata\player_ready]], "w"):close()
end
